package com.rationportal.service; import com.rationportal.model.RationCard; import com.rationportal.repository.RationCardRepository; import org.springframework.stereotype.Service; import org.springframework.web.multipart.MultipartFile; import java.io.BufferedReader; import java.io.InputStreamReader; import java.nio.charset.StandardCharsets; @Service public class RationCardImportService { private final RationCardRepository repository; public RationCardImportService(RationCardRepository repository){this.repository=repository;} public int importCsv(MultipartFile file) throws Exception { int count=0; try(BufferedReader reader=new BufferedReader(new InputStreamReader(file.getInputStream(),StandardCharsets.UTF_8))){ String line; boolean header=true; while((line=reader.readLine())!=null){ if(header){header=false; continue;} if(line.isBlank()) continue; String[] p=line.split(",",-1); if(p.length<7) continue; RationCard card=new RationCard(); card.setRationCardNumber(p[0].trim()); card.setCardType(p[1].trim()); card.setHeadOfFamily(p[2].trim()); card.setAddress(p[3].trim()); card.setDistrict(p[4].trim()); card.setState(p[5].trim()); card.setStatus(p[6].trim()); repository.save(card); count++; } } return count; } }
